    g.E = mix(g.E, max(g.E, pow(Dt, .9)*.7), w); g.A = mix(g.A, max(g.A, pow(Dt, 1.1)*.8), w);
    g.c = mix(g.c, mix(g.vif, g.coeur, .25), w*.5*Dt);
